  function setLang(next){lang=copy[next]?next:'bn';document.documentElement.lang=lang;document.documentElement.dataset.lang=lang;const url=new URL(location.href);if(lang==='bn')url.searchParams.delete('lang');else url.searchParams.set('lang',lang);history.replaceState(null,'',url);$$('.language button').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));$$('[data-i18n]').forEach(el=>{const v=copy[lang][el.dataset.i18n];if(v)el.textContent=v});$$('[data-i18n-html]').forEach(el=>{const v=copy[lang][el.dataset.i18nHtml];if(v)el.innerHTML=v});$$('[data-i18n-placeholder]').forEach(el=>{const v=copy[lang][el.dataset.i18nPlaceholder];if(v)el.placeholder=v});$('#brandLogo').src=lang==='bn'?'../img/logo/logo-navbar-bn-clear.png':'../img/logo/logo-navbar-en-clear.png';renderIncidents();renderPeople()}
  function renderIncidents(){const q=$('#incidentSearch').value.trim().toLowerCase(),cat=$('#incidentCategory').value;const list=incidents.filter(x=>(cat==='all'||x.cat===cat)&&(!q||[x.year,tr(x.title),tr(x.summary),tr(x.what)].join(' ').toLowerCase().includes(q)));$('#incidentCount').textContent=list.length;$('#incidentGrid').innerHTML=list.length?list.map((x,i)=>`<article class="incident-card ${x.cat==='scope'?'scope-card':''}" id="${esc(x.id)}" style="--i:${i}"><div class="incident-image"><img src="${esc(x.image)}" alt="${esc(tr(x.title))}" loading="lazy" referrerpolicy="no-referrer"></div><div class="incident-content"><div class="incident-meta"><span>${esc(tr(x.date))}</span><b>${esc(copy[lang][x.cat]||x.cat)}</b></div><h3>${esc(tr(x.title))}</h3><p class="incident-summary">${esc(tr(x.summary))}</p><strong class="incident-stat">${esc(tr(x.stat))}</strong><div class="incident-details"><div><div class="detail-inner"><p><strong>${esc(copy[lang].whatHappened)}:</strong> ${esc(tr(x.what))}</p><p><strong>${esc(copy[lang].whyMatters)}:</strong> ${esc(tr(x.why))}</p><p><strong>${esc(copy[lang].statusLabel)}:</strong> ${esc(tr(x.status))}</p>${x.sources.length?`<div class="source-links"><strong>${esc(copy[lang].sources)}:</strong>${x.sources.map(s=>`<a href="${esc(s[1])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a>`).join('')}</div>`:''}<p><strong>${esc(copy[lang].imageSource)}:</strong> ${esc(x.credit)}</p></div></div></div><button class="incident-toggle" type="button" aria-expanded="false">${esc(copy[lang].readMore)}</button></div></article>`).join(''):`<p>${esc(copy[lang].noRecords)}</p>`;$$('.incident-toggle').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.incident-card'),open=card.classList.toggle('open');btn.setAttribute('aria-expanded',String(open));btn.textContent=open?copy[lang].close:copy[lang].readMore}))}
  function openIncidentModal(id){const x=incidents.find(item=>item.id===id),dialog=$('#incidentModal');if(!x||!dialog)return;$('#modalContent').innerHTML=`<div class="modal-visual"><img src="${esc(x.image)}" alt="${esc(tr(x.title))}" referrerpolicy="no-referrer"><div><span>${esc(tr(x.date))}</span><b>${esc(copy[lang][x.cat]||x.cat)}</b></div></div><div class="modal-body"><p class="eyebrow">${esc(copy[lang].documentedFigure)}</p><strong class="modal-stat">${esc(tr(x.stat))}</strong><h2>${esc(tr(x.title))}</h2><p class="modal-lead">${esc(tr(x.summary))}</p><div class="modal-facts"><section><b>01</b><h3>${esc(copy[lang].whatHappened)}</h3><p>${esc(tr(x.what))}</p></section><section><b>02</b><h3>${esc(copy[lang].whyMatters)}</h3><p>${esc(tr(x.why))}</p></section><section><b>03</b><h3>${esc(copy[lang].statusLabel)}</h3><p>${esc(tr(x.status))}</p></section></div><div class="modal-sources"><strong>${esc(copy[lang].sources)}</strong>${x.sources.map(s=>`<a href="${esc(s[1])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a>`).join('')}<small>${esc(copy[lang].imageSource)}: ${esc(x.credit)}</small></div></div>`;dialog.showModal();document.body.classList.add('modal-open');history.replaceState(null,'',`#${x.id}`)}
  function closeIncidentModal(){const dialog=$('#incidentModal');if(dialog?.open)dialog.close();document.body.classList.remove('modal-open');history.replaceState(null,'',location.pathname+location.search+'#evidence')}
  function renderIncidentsV2(){const q=$('#incidentSearch').value.trim().toLowerCase(),cat=$('#incidentCategory').value;const list=incidents.filter(x=>(cat==='all'||x.cat===cat)&&(!q||[x.year,tr(x.title),tr(x.summary),tr(x.what)].join(' ').toLowerCase().includes(q)));$('#incidentCount').textContent=list.length;$('#incidentGrid').innerHTML=list.length?list.map((x,i)=>`<article class="incident-card" id="${esc(x.id)}" style="--i:${i}"><div class="incident-image"><img src="${esc(x.image)}" alt="${esc(tr(x.title))}" loading="lazy" referrerpolicy="no-referrer"></div><div class="incident-content"><div class="incident-meta"><span>${esc(tr(x.date))}</span><b>${esc(copy[lang][x.cat]||x.cat)}</b></div><h3>${esc(tr(x.title))}</h3><p class="incident-summary">${esc(tr(x.summary))}</p><strong class="incident-stat">${esc(tr(x.stat))}</strong><button class="incident-toggle" type="button" data-incident="${esc(x.id)}">${esc(copy[lang].readMore)}</button></div></article>`).join(''):`<p>${esc(copy[lang].noRecords)}</p>`;$$('[data-incident]').forEach(btn=>btn.addEventListener('click',()=>openIncidentModal(btn.dataset.incident)))}
